package com.adityansh.zerodha.service;
import com.adityansh.zerodha.dto.TradeRequest; import com.adityansh.zerodha.entity.*; import com.adityansh.zerodha.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class TradingService { private final UserRepository users; private final StockRepository stocks; private final HoldingRepository holdings; private final OrderRepository orders; public TradingService(UserRepository u,StockRepository s,HoldingRepository h,OrderRepository o){users=u;stocks=s;holdings=h;orders=o;}
 public List<Stock> stocks(){return stocks.findAll();} public User user(Long id){return users.findById(id).orElseThrow();} public List<Holding> holdings(Long id){return holdings.findByUser(user(id));} public List<Order> orders(Long id){return orders.findByUserOrderByCreatedAtDesc(user(id));}
 @Transactional public Order trade(Long id,TradeRequest req,Order.Type type){User u=user(id);Stock s=stocks.findBySymbol(req.symbol().toUpperCase()).orElseThrow(()->new RuntimeException("Stock not found"));double total=s.getPrice()*req.quantity(); if(type==Order.Type.BUY){if(u.getCashBalance()<total)throw new RuntimeException("Insufficient cash balance");u.setCashBalance(u.getCashBalance()-total);Holding h=holdings.findByUserAndStock(u,s).orElse(new Holding(null,u,s,0,0));double newAvg=((h.getAveragePrice()*h.getQuantity())+total)/(h.getQuantity()+req.quantity());h.setQuantity(h.getQuantity()+req.quantity());h.setAveragePrice(newAvg);holdings.save(h);}else{Holding h=holdings.findByUserAndStock(u,s).orElseThrow(()->new RuntimeException("No holding for this stock"));if(h.getQuantity()<req.quantity())throw new RuntimeException("Insufficient shares");h.setQuantity(h.getQuantity()-req.quantity());if(h.getQuantity()==0)holdings.delete(h);else holdings.save(h);u.setCashBalance(u.getCashBalance()+total);}users.save(u);return orders.save(new Order(null,u,s,type,req.quantity(),s.getPrice(),java.time.LocalDateTime.now()));}
}
